const scriptPromises=new Map();
function loadScriptOnce(src,test){
 if(test?.())return Promise.resolve(true);
 if(scriptPromises.has(src))return scriptPromises.get(src);
 const p=new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=src;el.async=true;el.onload=()=>resolve(true);el.onerror=()=>reject(new Error('Impossible de charger '+src));document.head.appendChild(el)});
 scriptPromises.set(src,p);return p;
}
async function ensureSupabase(){if(window.supabase)return true;try{await loadScriptOnce(LIB_URLS.supabase,()=>!!window.supabase);return !!window.supabase}catch(e){console.warn(e);return false}}
async function ensurePdfLibs(){try{if(!window.jspdf?.jsPDF)await loadScriptOnce(LIB_URLS.jspdf,()=>!!window.jspdf?.jsPDF);if(window.jspdf?.jsPDF){const test=()=>{try{return typeof new window.jspdf.jsPDF().autoTable==='function'}catch{return false}};if(!test())await loadScriptOnce(LIB_URLS.autotable,test)}return !!window.jspdf?.jsPDF}catch(e){console.warn(e);return false}}
async function ensureQr(){if(window.QRCode)return true;try{await loadScriptOnce(LIB_URLS.qrcode,()=>!!window.QRCode);return !!window.QRCode}catch(e){console.warn(e);return false}}
const now=new Date();
