const tempText=n=>Number.isFinite(Number(n))?`${Number(n).toFixed(1).replace('.',',')} °C`:'—';
const fmtDate=s=>new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(`${s}T12:00:00`));
const fmtDateTime=s=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(s));
const frenchMonth=mk=>new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric'}).format(new Date(`${mk}-01T12:00:00`));
